void tick_screen_main_screen() {
}

void create_screens() {
    lv_disp_t *dispp = lv_disp_get_default();
    // dark = FALSE. This is a white e-paper panel: ink is black on paper.
    // The dark theme paints every surface near-black, which on hardware
    // means driving the whole panel to ink on every refresh.
    lv_theme_t *theme = lv_theme_default_init(dispp, lv_color_black(), lv_color_black(),
                                              false, LV_FONT_DEFAULT);
    lv_disp_set_theme(dispp, theme);
    create_screen_main_screen();
}

typedef void (*tick_screen_func_t)();
tick_screen_func_t tick_screen_funcs[] = { tick_screen_main_screen };
void tick_screen(int screen_index) { tick_screen_funcs[screen_index](); }
void tick_screen_by_id(enum ScreensEnum screenId) { tick_screen_funcs[screenId - 1](); }